previewCss:
.darma-loader-darma-b8-fireworks-burst { --accent: var(--loader-color, #f472b6); --accent-2: var(--loader-secondary-color, #fde047); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; }
.darma-loader-darma-b8-fireworks-burst span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size, 88px) * .08); height: calc(var(--loader-size, 88px) * .08); margin: calc(var(--loader-size, 88px) * -.04) 0 0 calc(var(--loader-size, 88px) * -.04); border-radius: 50%; background: var(--accent); animation: darma-loader-darma-b8-fireworks-burst-burst calc(var(--loader-speed, 1s) * 1.6) ease-out infinite; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(even) { background: var(--accent-2); }
.darma-loader-darma-b8-fireworks-burst span:nth-child(1) { --a: 0deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(2) { --a: 36deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(3) { --a: 72deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(4) { --a: 108deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(5) { --a: 144deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(6) { --a: 180deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(7) { --a: 216deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(8) { --a: 252deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(9) { --a: 288deg; }
.darma-loader-darma-b8-fireworks-burst span:nth-child(10) { --a: 324deg; }
@keyframes darma-loader-darma-b8-fireworks-burst-burst { 0% { transform: rotate(var(--a)) translateX(0) scale(1); opacity: 1; } 70% { opacity: 1; } 100% { transform: rotate(var(--a)) translateX(calc(var(--loader-size, 88px) * .42)) scale(.2); opacity: 0; } }

